320	function isConfigurationPropertySchema(x: IConfigurationPropertySchema | { [path: string]: IConfigurationPropertySchema }): x is IConfigurationPropertySchema {
321		return (typeof x.type !== 'undefined' || typeof x.anyOf !== 'undefined');
322	}
323	
324	// Add properties from the Editor Option Registry
325	for (const editorOption of editorOptionsRegistry) {
326		const schema = editorOption.schema;
327		if (typeof schema !== 'undefined') {
328			if (isConfigurationPropertySchema(schema)) {
329				// This is a single schema contribution
330				editorConfiguration.properties![`editor.${editorOption.name}`] = schema;
331			} else {
332				for (const key in schema) {
333					if (Object.hasOwnProperty.call(schema, key)) {
334						editorConfiguration.properties![key] = schema[key];
335					}
336				}
337			}
338		}
339	}
340	
341	let cachedEditorConfigurationKeys: { [key: string]: boolean } | null = null;
342	function getEditorConfigurationKeys(): { [key: string]: boolean } {
343		if (cachedEditorConfigurationKeys === null) {
344			cachedEditorConfigurationKeys = <{ [key: string]: boolean }>Object.create(null);
345			Object.keys(editorConfiguration.properties!).forEach((prop) => {
346				cachedEditorConfigurationKeys![prop] = true;
347			});
348		}
349		return cachedEditorConfigurationKeys;
350	}
351	
352	export function isEditorConfigurationKey(key: string): boolean {
353		const editorConfigurationKeys = getEditorConfigurationKeys();
354		return (editorConfigurationKeys[`editor.${key}`] || false);
355	}
356	
357	export function isDiffEditorConfigurationKey(key: string): boolean {
358		const editorConfigurationKeys = getEditorConfigurationKeys();
359		return (editorConfigurationKeys[`diffEditor.${key}`] || false);
360	}
361	
362	const configurationRegistry = Registry.as<IConfigurationRegistry>(Extensions.Configuration);
363	configurationRegistry.registerConfiguration(editorConfiguration);
364	
365	export async function registerEditorFontConfigurations(getFontSnippets: () => Promise<IJSONSchemaSnippet[]>) {
366		const editorKeysWithFont = ['editor.fontFamily'];
367		const fontSnippets = await getFontSnippets();
368		for (const key of editorKeysWithFont) {
369			if (
370				editorConfiguration.properties && editorConfiguration.properties[key]
371			) {
372				editorConfiguration.properties[key].defaultSnippets = fontSnippets;
373			}
374		}
375	}
